import sys, re
src, dst = sys.argv[1], sys.argv[2]
t = open(src, encoding='utf-8').read()
def R(old, new, cnt=1):
    global t
    n = t.count(old)
    if n != cnt: raise SystemExit(f'COUNT {n} != {cnt}: {old[:80]}')
    t = t.replace(old, new)

# 표 번호 참조를 자리표시자로
for n, cap in [(1,'판결 코딩 항목'),(3,'선행연구의 쟁점별 비교'),(7,'분석 사례의 비교'),(16,'3단계 분석 틀과 디지털 증거의 대응')]:
    t = t.replace(f'〈표 {n}〉', '{{T:'+cap+'}}')
assert '〈표 ' not in t

i0 = t.index('> **개고 안내(v0.9'); i1 = t.index('\n', i0)
t = t[:i0] + "> **개고 안내(v1.0, 제출 전 삭제)** v0.9 검토 결과에 따라 ① 가장 가까운 선행연구(박혜원 2026, 김민석 2021)와 간첩죄·외환의 죄·드론 포렌식·수사체계 관련 문헌 16편을 RISS 서지·초록으로 확인하여 선행연구를 일곱 흐름으로 재구성하고 본 연구와의 차이를 밝혔고, ② 수원 사건 항소심(수원고법 2026.8.27. 항소 기각)과 촬영물 공유에 관한 검찰 주장 보도를 반영하였으며, ③ 군사기지법·같은 법 시행령(별표 1)·항공안전법 원문에 근거하여 제2장에 보호구역 제도와 비행 규제의 절을 새로 두고, 보호구역 범위에 관한 제3장의 서술을 바로잡았다. 제5장에는 드론 포렌식 연구의 성과와 한계를 추가하였다." + t[i1:]

# ---------- 제1장 ----------
R("상업용 위성영상과 인터넷 지도가 보편화되면서 상당수 군사시설의 위치는 공개된 정보가 되었다.",
  "상업용 위성영상과 인터넷 지도가 보편화되면서 상당수 군사시설의 위치는 공개된 정보가 되었다.[[fn: 포털사이트의 지도와 실사 지도 서비스에 군사시설 등 국가중요시설의 명칭과 사진이 노출되는 실태에 관하여는 조득성, 「국가중요시설의 보안 문제 식별 및 대응방안 연구: 군사시설 및 기지를 중심으로」, 국민대학교 비즈니스IT전문대학원 박사학위논문, 2026 참조.]]")
R("| 수원 공군기지 촬영 | 2025.3. 적발, 2026.5. 선고 |", "| 수원 공군기지 촬영 | 2025.3. 적발, 2026.5. 선고, 2026.8. 항소 기각 |")
R("| 부산 해군작전사령부 드론 촬영 | 2024.6. 적발, 2026.6. 선고 |", "| 부산 해군작전사령부 드론 촬영 | 2024.6. 적발, 2026.6. 선고, 2026.10. 항소 기각 |")
R("관련 연구는 다음 여섯 흐름으로 나뉜다.", "관련 연구는 다음 일곱 흐름으로 나뉜다.")
R("이 연구들은 2026년 개정의 이론적 배경이 되었으나, 기밀이 아닌 시설의 외부 촬영과 일반이적죄의 관계는 다루지 않았다.",
  "간첩죄의 '적국' 요건과 정비 방안에 관한 논의는 그 이전부터 이어져 왔다.[[fn: 박상기, 「간첩죄에 관한 소고」, 『형사정책연구』 통권 제71호, 한국형사정책연구원, 2007, 567-580면; 정영일·황태정, 「간첩죄의 해석론과 개선방향」, 『형사정책』 제21권 제2호, 한국형사정책학회, 2009, 393-424면; 신의기, 「국제환경의 변화와 간첩죄 규정 정비방안」, 『국가안보와 전략』 제10권 제4호, 국가안보전략연구원, 2010, 111-152면.]] 이 연구들은 2026년 개정의 이론적 배경이 되었으나, 기밀이 아닌 시설의 외부 촬영과 일반이적죄의 관계는 다루지 않았다.")
R("이 흐름은 기밀 취급자의 내부 유출을 전제로 하므로,",
  "백인천은 군사기밀보호법 위반 판결 55건을 분석하여 1심 집행유예율이 군사법원 55%, 민간법원 64%로 높고 비밀등급이 낮을수록 집행유예 가능성이 높아진다고 보았다.[[fn: 백인천, 「군사기밀 보호법 위반에 대한 집행유예 양형요인 연구」, 경찰대학 치안대학원 석사학위논문, 2020.]] 이 흐름은 기밀 취급자의 내부 유출을 전제로 하므로,")
i0 = t.index("셋째, 군사시설 드론 대응론이다.")
i1 = t.index("\n", i0)
old3 = t[i0:i1]
assert old3.endswith("이들은 탐지와 무력화에 초점을 두며, 촬영 그 자체에 대한 형사법적 평가는 다루지 않는다.")
new3 = old3.replace("셋째, 군사시설 드론 대응론이다.", "셋째, 드론과 군사시설에 관한 연구이다.") + """ 형사법의 관점에서는 김민석이 국방 분야 드론의 형사법적 쟁점을 다루면서, 드론을 이용한 주요시설 침입이나 촬영은 현행 형법으로 처벌할 수 없으므로 비교법적 검토를 통해 처벌 조항을 신설해야 한다고 보았다.[[fn: 김민석, 「국방 분야 드론에 대한 형사법적 대응 및 발전방안 연구: 군사용 드론을 중심으로」, 연세대학교 대학원 석사학위논문, 2021.]] 김동석은 군사시설 인근의 미승인 드론 비행을 항공안전법과 군사기지법으로 규율하지 못하는 공백을 지적하고, 전파법상 전파차단장치 사용을 즉시강제의 근거로 검토하였다.[[fn: 김동석, 「군(軍)의 드론 대응에 있어서의 법적쟁점 연구」, 『해양과학기술』 제60권, 해군사관학교 해양연구소, 2025, 251-264면.]] 항공안전법이 드론을 중량으로 구분하고 있어 군사기지에 대한 드론 불법침입을 처벌하려면 명확한 정의가 필요하다는 지적도 있다.[[fn: 정진만·김용근·정종택·신동일, 「항공작전기지 보호를 위한 법령 개정연구: 드론을 중심으로」, 『한국재난정보학회 학술발표대회 논문집』 2025, 179-180면.]]
본 연구와 가장 가까운 연구는 박혜원의 연구이다. 이 연구는 드론에 의한 국가중요시설과 군사기지의 상공 침입을 대상으로 항공안전법, 군사기지법, 간첩죄, 주거침입죄, 군사기밀보호법의 적용 한계를 검토하고, 간첩죄가 '적국을 위한 목적'을 요구하여 적용에 논란이 있다고 보았다. 그리고 간첩죄와 달리 별도의 목적을 요하지 않는 추상적 위험범으로서 '(가칭) 국가중요시설등상공침입죄'를 신설하고 위험성에 따른 단계적 형벌체계를 두는 한편, 드론 무력화 권한과 면책 규정을 법제화하자고 제안하였다.[[fn: 박혜원, 「드론 상공침입에 대한 형사법적 대응방안 연구」, 서울대학교 대학원 석사학위논문, 2026.]] 본 연구는 현행 규범의 처벌 공백을 지적하고 단계적 형벌 체계를 제안한다는 방향을 공유하지만 다음 점에서 다르다. 첫째, 대상 행위가 상공 '침입'이 아니라 정보를 생성하는 '촬영'이며 드론에 한정되지 않는다. 둘째, 2026년 5월 이후 선고된 일반이적죄 판결과 같은 해 9월 시행된 제98조의2를 분석 대상으로 하여, 일반이적죄의 위험 판단과 제98조의2와의 경합 및 처벌의 역전을 다룬다. 셋째, 구성요건과 디지털 증거의 대응, 수사 주체와 인계라는 입증과 수사 실무의 문제를 다룬다. 넷째, 본 연구가 제안하는 2단계 구성요건은 목적을 요하지 않는 침입죄가 아니라 정보수집 목적을 요건으로 하는 촬영죄로서, 무단 촬영과 일반이적 사이를 메우는 기능을 한다."""
t = t[:i0] + new3 + t[i1:]
R("다만 이 연구는 군인을 주된 적용 대상으로 하는 군형법을 다루었고, 민간인과 외국인에 대한 형법 제99조의 적용은 검토하지 않았다.",
  "다만 이 연구는 군인을 주된 적용 대상으로 하는 군형법을 다루었고, 민간인과 외국인에 대한 형법 제99조의 적용은 검토하지 않았다. 형법의 외환의 죄에 관해서는, 이 규정들이 전시형법적·국가주의적 특성을 가장 짙게 지니고 있다고 보고 외환유치·여적, 이적·군수계약불이행, 간첩의 세 분야로 나누어 외국 법제와 비교한 입법론적 검토가 있다.[[fn: 정영일·황태정, 「\"외환의 죄\"에 관한 입법론적 검토」, 『경희법학』 제46권 제3호, 경희대학교 법학연구소, 2011, 77-114면.]] 이 연구도 2026년 개정과 촬영 행위는 다루지 않았다.")
R("이 연구들은 일반 이론으로서 일반이적죄나 개정 간첩죄에 적용된 것은 아니며, 본 연구는 이를 제99조의 위험 판단과 제98조의2와의 관계에 적용한다.\n",
  """이 연구들은 일반 이론으로서 일반이적죄나 개정 간첩죄에 적용된 것은 아니며, 본 연구는 이를 제99조의 위험 판단과 제98조의2와의 관계에 적용한다.
일곱째, 드론 포렌식과 수사체계에 관한 연구이다. 드론 포렌식 연구는 DJI 기종별 비행기록의 암호화 방식과 복호화,[[fn: 이영우·김주환·유지현·윤주범, 「비행 로그 복호화 방식에 따른 DJI 드론 분류」, 『정보보호학회논문지』 제32권 제1호, 2022, 77-88면.]] 비행 로그 파일의 유형 분류와 분석,[[fn: 조수경·이성현·성민규·조수빈·박정흠, 「DJI 드론의 비행 로그 파일 유형 분류 및 분석 기법 연구」, 『디지털 포렌식 연구』 제17권 제1호, 한국디지털포렌식학회, 2023, 13-25면.]] 삭제된 비행기록의 복구 가능성,[[fn: 윤여훈·윤주범, 「DJI 드론 모델별 삭제 비행기록 복구 가능성 분석」, 『정보보호학회논문지』 제33권 제4호, 한국정보보호학회, 2023, 609-619면.]] 통신 패킷에 기반한 비행기록 분석,[[fn: 윤여훈·윤주범, 「DUML 패킷 분석을 통한 드론 비행기록 포렌식 시스템」, 『정보보호학회논문지』 제34권 제1호, 한국정보보호학회, 2024, 103-114면.]] 비행제어기와 지상통제시스템(GCS)의 증거 분석,[[fn: 김영준, 「드론의 디지털 증거 수집과 분석에 관한 연구: GCS(Ground Control System)를 중심으로」, 동국대학교 석사학위논문, 2020.]] 조종기의 사용자 행위 분석[[fn: 이성원, 「디지털 포렌식을 위한 DJI 드론 조종기의 사용자 행위 분석」, 부산가톨릭대학교 일반대학원 석사학위논문, 2024.]]을 다루었다. 이 연구들은 비행기록을 획득하고 해석하는 기술을 제시하였으나, 그 결과를 보호구역 경계와 대조하여 구성요건 해당성을 판단하는 절차는 다루지 않았다. 수사체계에 관해서는, 방산기술 유출 사건은 경찰·검찰 중심의 기술범죄 수사체계에서, 방첩 사건은 국가정보원과 군 방첩기관 중심의 체계에서 다루어지는 이원적 구조가 같은 침해 행위를 '기술범죄'와 '안보범죄'로 분절 처리하게 만든다는 연구가 있다.[[fn: 이상범, 「통합적 방산안보 수사체계에 관한 연구」, 명지대학교 대학원 박사학위논문, 2026.]] 이 문제의식은 죄명의 확대에 따라 수사기관이 바뀌는 촬영 사건에도 그대로 적용된다.
""")
