# ---------- 표 번호 재계산 ----------
caps = re.findall(r'^@@cap (.*)$', t, re.M)
def sub(m):
    c = m.group(1)
    return f'〈표 {caps.index(c)+1}〉'
t = re.sub(r'\{\{T:([^}]+)\}\}', sub, t)
open(dst, 'w', encoding='utf-8').write(t)
print('ok tables', len(caps))
